<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';AuthService::boot();$user=AuthService::requireLogin();$gid=(int)($_GET['game']??$_POST['game_id']??0);if($gid<1){header('Location: ./');exit;}$error=null;$notice=null;
try{$membership=LobbyService::lobbyState($gid,(int)$user['user_id']);if($membership['game']['status']==='LOBBY'){header('Location: lobby.php?game='.$gid);exit;}LobbyService::tick($gid);}catch(Throwable$e){http_response_code(403);die(e($e->getMessage()));}
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='decide')LobbyService::choose($gid,(int)$user['user_id'],(int)$_POST['decision_id'],(string)$_POST['option_code']);if($action==='rate'){LobbyService::rate($gid,(int)$user['user_id'],(int)$_POST['rating'],(string)($_POST['review']??''));$notice='Thank you for rating this story.';}header('Location: play.php?game='.$gid.($notice?'&rated=1':''));exit;}catch(Throwable$e){$error=$e->getMessage();}}
$state=LobbyService::lobbyState($gid,(int)$user['user_id']);$sid=(int)$state['game']['simulation_id'];$snap=SimulationService::snapshot($sid);$sim=$snap['simulation'];$character=LobbyService::playerCharacter($gid,(int)$user['user_id']);if($character){foreach($snap['characters']as$c)if((int)$c['character_id']===(int)$character['character_id']){$character=$c;break;}}$rated=isset($_GET['rated']);
$outcome=[];if($sim['status']==='COMPLETE'){$q=db()->prepare('SELECT label_text,source_type,source_key FROM plot_outcome_dimensions WHERE plot_id=? AND active=1 ORDER BY sort_order,outcome_dimension_id');$q->execute([$sim['plot_id']]);foreach($q->fetchAll()as$d){$v='UNKNOWN';if($d['source_type']==='FACTOR'){foreach($snap['factors']as$f)if($f['factor_code']===$d['source_key']){$n=(int)$f['current_value'];$v=$n<35?'LOW':($n<65?'MID':'HIGH');break;}}else{$s=GenericStateService::getByKey($sid,(string)$d['source_key']);if($s['exists'])$v=strtoupper((string)$s['value']);}$outcome[]=trim($d['label_text'].' '.$v);}}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($sim['title'])?> · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#e9edf3}*{box-sizing:border-box}body{margin:0}.bar{position:sticky;top:0;z-index:10;background:#111827;color:#fff;padding:13px 18px}.barin,.shell{max-width:1120px;margin:auto}.barin{display:flex;justify-content:space-between;align-items:center;gap:12px}.bar a{color:#fff}.shell{padding:22px 18px}.status{font-weight:850}.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(290px,.65fr);gap:18px}.card{background:#fff;border:1px solid #d8e0ea;border-radius:15px;padding:19px;margin-bottom:16px}.event{border-left:4px solid #6366f1;padding:8px 0 8px 14px;margin:13px 0}.event small,.muted{color:#64748b}.private{background:#fff7ed;border-color:#fed7aa}.decision{border:2px solid #7c3aed;background:#f5f3ff}.option{display:block;width:100%;text-align:left;background:#fff;border:1px solid #c4b5fd;border-radius:9px;padding:11px;margin:8px 0;font:inherit;cursor:pointer}.btn{border:0;border-radius:9px;background:#4f46e5;color:#fff;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}.history{padding:9px 0;border-bottom:1px solid #e5e7eb}.outcome{background:#ecfdf5;border:2px solid #6ee7b7}.outcome li{margin:6px 0}.error{background:#fee2e2;color:#991b1b;padding:12px;border-radius:10px}.progress{height:8px;background:#374151;border-radius:999px;overflow:hidden;width:180px}.progress span{display:block;height:100%;background:#818cf8}@media(max-width:780px){.layout{grid-template-columns:1fr}.barin{align-items:flex-start;flex-wrap:wrap}}
</style></head><body><header class="bar"><div class="barin"><div><b><?=e($sim['title'])?></b><div class="muted"><?=e($sim['current_phase'])?> · <?=gmdate('i:s',(int)$sim['elapsed_seconds'])?> / <?=gmdate('i:s',(int)$sim['duration_seconds'])?></div></div><div class="progress"><span style="width:<?=min(100,round(100*(int)$sim['elapsed_seconds']/max(1,(int)$sim['duration_seconds'])))?>%"></span></div><a href="./">My games</a></div></header><main class="shell"><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($rated):?><p class="card">Thank you for rating this story.</p><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card outcome"><h1>The story is complete</h1><ul><?php foreach($outcome as$o):?><li><?=e($o)?></li><?php endforeach;?></ul></section><?php endif;?>
<div class="layout"><div><section class="card"><h2>What everyone can see</h2><?php if(!$snap['world']):?><p class="muted">The story is beginning…</p><?php endif;?><?php foreach($snap['world']as$w):?><article class="event"><small><?=gmdate('i:s',(int)$w['event_second'])?> · <?=e($w['phase'])?></small><h3><?=e($w['headline'])?></h3><div><?=e($w['event_text'])?></div></article><?php endforeach;?></section></div><aside>
<?php if($character):?><section class="card private"><small>Your private character view</small><h2><?=e($character['name'])?></h2><p><?=e($character['description'])?></p><p><b>Where you are:</b> <?=e($character['current_location'])?></p><p><b>Your goal:</b> <?=e($character['goal_text'])?></p><p><b>Your fear:</b> <?=e($character['fear_text'])?></p><p><b>What only you know:</b><br><?=e($character['private_knowledge'])?></p></section>
<?php foreach($character['open_decisions'] as$d):?><section class="card decision"><h2>Choose what you do</h2><p><?=e($d['prompt_text'])?></p><?php foreach($d['options']as$o):?><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="decide"><input type="hidden" name="decision_id" value="<?=(int)$d['decision_id']?>"><input type="hidden" name="option_code" value="<?=e($o['option_code'])?>"><button class="option"><b><?=e($o['label'])?></b><?php if(!empty($o['description'])):?><br><small><?=e($o['description'])?></small><?php endif;?></button></form><?php endforeach;?></section><?php endforeach;?>
<section class="card"><h2>Your story so far</h2><?php foreach(array_reverse($character['history'])as$h):?><div class="history"><small><?=gmdate('i:s',(int)$h['event_second'])?> · <?=e($h['history_type'])?></small><br><b><?=e($h['title'])?></b><br><?=e($h['detail_text'])?></div><?php endforeach;?></section><?php else:?><section class="card"><h2>Spectator view</h2><p>You did not select a character before the game began.</p></section><?php endif;?>
<?php if($sim['status']==='COMPLETE'):?><section class="card"><h2>Rate this story</h2><form method="post"><?=csrf_field()?><input type="hidden" name="game_id" value="<?=$gid?>"><input type="hidden" name="action" value="rate"><label>Rating <select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select></label><p><textarea name="review" rows="4" style="width:100%" placeholder="Optional review"></textarea></p><button class="btn">Save rating</button></form></section><?php endif;?></aside></div></main><?php if($sim['status']==='RUNNING'):?><script>setTimeout(()=>location.reload(),3000);</script><?php endif;?></body></html>
